-- MT2009_PLUS_YOHARA_RASY_V1: then the races (bits 0-10) the data file's RACE fixes (Jotun Thrym: a devil).
SET NAMES utf8mb4;
-- wiatr: 4260,4261,4262,4263,4264,4265,4267,4268,4269,4270,4271,4272,4403
UPDATE world.mob_proto SET setRaceFlag = ((setRaceFlag + 0) & ~129024) | 16384 WHERE vnum IN (4260,4261,4262,4263,4264,4265,4267,4268,4269,4270,4271,4272,4403);
-- no element (the Metins): 8126,8127
